CARDS = [
 ('Дискримінант квадратного рівняння ax² + bx + c = 0 і кількість коренів', 'D = b² − 4ac. D > 0 — два корені x = (−b ± √D)/(2a); D = 0 — один корінь x = −b/(2a); D < 0 — коренів немає.'),
 ('Теорема Вієта для рівняння x² + px + q = 0 (і для ax² + bx + c = 0)', 'x₁ + x₂ = −p, x₁x₂ = q. Для ax² + bx + c = 0: x₁ + x₂ = −b/a, x₁x₂ = c/a. Працює, коли D ≥ 0.'),
 ('Вирази через суму й добуток коренів', 'x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂; x₁³ + x₂³ = (x₁ + x₂)³ − 3x₁x₂(x₁ + x₂); (x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂; 1/x₁ + 1/x₂ = (x₁ + x₂)/(x₁x₂).'),
 ('Розкладання квадратного тричлена на множники', 'ax² + bx + c = a(x − x₁)(x − x₂), де x₁, x₂ — корені. Якщо D < 0, на дійсні множники тричлен не розкладається.'),
 ('Неповні квадратні рівняння: як розв’язувати', 'ax² + bx = 0 → x(ax + b) = 0 → x = 0 або x = −b/a (не діліть на x — втратите корінь). ax² + c = 0 → x² = −c/a: два корені ±√(−c/a), якщо −c/a > 0, інакше коренів немає.'),
 ('Лінійне рівняння ax = b: скільки коренів', 'a ≠ 0 — один корінь x = b/a; a = 0 і b ≠ 0 — коренів немає; a = 0 і b = 0 — безліч коренів (будь-яке x).'),
 ('Лінійна нерівність: головне правило', 'Під час множення чи ділення на від’ємне число знак нерівності змінюється на протилежний: −2x > 6 ⇒ x < −3.'),
 ('Метод інтервалів: алгоритм', '1) звести до вигляду f(x) ∨ 0; 2) розкласти на множники й знайти нулі чисельника та знаменника; 3) позначити їх на осі; 4) визначити знак на одному з проміжків і чергувати знаки; 5) обрати потрібні проміжки.'),
 ('Метод інтервалів: кінці проміжків і кратні корені', 'Нулі знаменника — завжди виколоті. Нулі чисельника — виколоті при строгій нерівності, зафарбовані при нестрогій. Корінь парної кратності знак не змінює (але при нестрогій нерівності ізольований нуль входить у розв’язок).'),
 ('Квадратна нерівність: розв’язок через корені', 'Якщо a > 0 і x₁ < x₂: ax² + bx + c < 0 ⇔ x ∈ (x₁; x₂); > 0 ⇔ x ∈ (−∞; x₁) ∪ (x₂; +∞). Якщо a < 0 — навпаки. Нестрога нерівність включає корені.'),
 ('Коли квадратна нерівність виконується для всіх x', 'ax² + bx + c > 0 для всіх x ⇔ a > 0 і D < 0. ax² + bx + c ≥ 0 для всіх x ⇔ a > 0 і D ≤ 0. Для < 0 — a < 0 і D < 0.'),
 ('Біквадратне рівняння ax⁴ + bx² + c = 0', 'Заміна t = x², t ≥ 0. Кожне t > 0 дає два корені x = ±√t; t = 0 — один (x = 0); t < 0 — жодного. Корені розташовані симетрично, тому їх сума дорівнює 0.'),
 ('Рівняння з модулем', '|u| = b (b > 0) ⇔ u = b або u = −b; |u| = b при b < 0 — коренів немає; |u| = |v| ⇔ u = v або u = −v; |u| = v ⇒ v ≥ 0 (перевірка).'),
 ('Нерівності з модулем', '|u| < r ⇔ −r < u < r; |u| > r ⇔ u < −r або u > r (r > 0). Якщо r < 0: |u| < r — розв’язків немає, |u| > r — усі x з ОДЗ.'),
 ('Сума модулів |x − a| + |x − b|', '|x − a| + |x − b| ≥ |a − b|; найменше значення досягається на відрізку між a і b. Тому при c < |a − b| рівняння = c розв’язків не має, при c = |a − b| розв’язок — весь відрізок, при c > |a − b| — два корені.'),
 ('Показникові рівняння: основні кроки', 'Зводьте до однієї основи: aᶠ = aᵍ ⇒ f = g (a > 0, a ≠ 1). Якщо число не є степенем основи: aˣ = N ⇒ x = logₐ N. Заміна t = aˣ > 0 для рівнянь типу a²ˣ + b·aˣ + c = 0.'),
 ('Показникові нерівності', 'При a > 1: aᶠ < aᵍ ⇔ f < g (знак зберігається). При 0 < a < 1: aᶠ < aᵍ ⇔ f > g (знак змінюється). Показникова функція завжди додатна, тому aˣ < N при N ≤ 0 розв’язків не має.'),
 ('Логарифмічні рівняння та ОДЗ', 'logₐ f = logₐ g ⇒ f = g, але обов’язково f > 0 і g > 0. logₐ f = k ⇔ f = aᵏ. Перевірте всі корені на ОДЗ: сторонні відкидайте.'),
 ('Логарифмічні нерівності', 'При a > 1: logₐ f < logₐ g ⇔ 0 < f < g. При 0 < a < 1: logₐ f < logₐ g ⇔ f > g > 0 (знак змінюється). Завжди додавайте ОДЗ: аргументи додатні.'),
 ('Властивості логарифмів для розв’язання рівнянь', 'logₐ(bc) = logₐ b + logₐ c; logₐ(b/c) = logₐ b − logₐ c; logₐ bᵏ = k·logₐ b; logₐ b = log_c b / log_c a; logₐ a = 1; logₐ 1 = 0. Після перетворень ОДЗ може розширитися — перевіряйте корені.'),
 ('Ірраціональні рівняння', '√f = g ⇒ f = g² і g ≥ 0 (перевірка!). √f = √g ⇒ f = g (f ≥ 0). Піднесення до квадрата може дати сторонні корені: підставляйте відповідь.'),
 ('Ірраціональні нерівності', '√f < g ⇔ f ≥ 0, g > 0, f < g². √f > g ⇔ [g < 0 і f ≥ 0] або [g ≥ 0 і f > g²]. √f ≥ 0 завжди, тому √f < (від’ємне) — розв’язків немає.'),
 ('Тригонометричні рівняння: формули', 'sin x = a → x = (−1)ⁿ arcsin a + πn; cos x = a → x = ± arccos a + 2πn; tg x = a → x = arctg a + πn (n ∈ ℤ). При |a| > 1 рівняння sin x = a і cos x = a коренів не мають.'),
 ('Особливі випадки тригонометричних рівнянь', 'sin x = 0 → πn; sin x = 1 → π/2 + 2πn; sin x = −1 → −π/2 + 2πn; cos x = 0 → π/2 + πn; cos x = 1 → 2πn; cos x = −1 → π + 2πn; tg x = 0 → πn.'),
 ('arcsin і arccos від’ємних значень', 'arcsin(−a) = −arcsin a; arccos(−a) = π − arccos a; arctg(−a) = −arctg a. Приклад: arccos(−1/2) = π − π/3 = 2π/3.'),
 ('Відбір коренів тригонометричного рівняння на проміжку', 'Запишіть серії розв’язків, підставляйте цілі n і перевіряйте, чи належить корінь проміжку. Не забувайте про кінці відрізка: x = 0 та x = 2π — різні корені на [0; 2π].'),
 ('Системи рівнянь: методи', 'Підстановка (виразити одну змінну); додавання/віднімання (зрівняти коефіцієнти); заміна змінних. Для симетричних систем використовуйте суму й добуток: x² + y² = (x + y)² − 2xy.'),
 ('Задачі на рух за течією', 'Власна швидкість v, швидкість течії u: за течією v + u, проти течії v − u. Час t = s / швидкість. Корінь, що дає v ≤ u або від’ємну швидкість, відкидають.'),
 ('Задачі на спільну роботу', 'Продуктивність = 1 / час. Спільна: 1/t₁ + 1/t₂ = 1/t. Якщо перший швидший на d год: 1/x + 1/(x + d) = 1/t — квадратне рівняння, від’ємний корінь відкидають.'),
 ('Рівняння з параметром: що перевірити', 'Для ax² + bx + c = 0 окремо розгляньте a = 0 (лінійне рівняння). Далі: кількість коренів залежить від знака D. Один корінь — D = 0; два різні — D > 0; жодного — D < 0.'),
 ('Вершина параболи і кількість розв’язків f(x) = k', 'Вершина x₀ = −b/(2a), y₀ = f(x₀). Якщо a > 0: f(x) = k має два корені при k > y₀, один при k = y₀, жодного при k < y₀. Для a < 0 — навпаки.'),
 ('Графічний розв’язок рівнянь і нерівностей', 'f(x) = g(x): корені — абсциси точок перетину графіків. f(x) > g(x): ті x, де графік f лежить вище за графік g. f(x) > 0 — графік вище осі x.'),
 ('Рівняння виду f(x)·g(x) = 0 та f(x)/g(x) = 0', 'Добуток дорівнює нулю, коли хоча б один множник нуль (інші мають існувати). Дріб дорівнює нулю, коли чисельник нуль, а знаменник не нуль.'),
 ('Нерівності x² > a² та x² < a²', 'x² < a² ⇔ |x| < a ⇔ −a < x < a; x² > a² ⇔ |x| > a ⇔ x < −a або x > a (a > 0). x² < 0 — розв’язків немає; x² ≥ 0 — усі x.'),
 ('Система нерівностей та сукупність', 'Система (фігурна дужка) — перетин розв’язків кожної нерівності: x має задовольняти всі. Сукупність (квадратна дужка) — об’єднання: достатньо виконання хоча б однієї.'),
]
